import urllib.request, json, logging
_log = logging.getLogger(__name__)
for record in records:
    try:
        payload = json.dumps({
            "task_id": record.id,
            "name": record.name,
            "description": record.description or "",
        }).encode("utf-8")
        req = urllib.request.Request(
            "http://10.1.0.31:19001/odoo-task",
            data=payload,
            headers={
                "Content-Type": "application/json",
                "X-Webhook-Secret": "frawo-odoo-webhook-2026",
            },
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=5) as resp:
            _log.info("ServAssi webhook ok task #%s", record.id)
    except Exception as e:
        _log.warning("ServAssi webhook failed task #%s: %s", record.id, e)
